class calculator:
    """Elementwise vector/scalar arithmetic, printed in place."""

    def __init__(self, values):
        """Store the vector this calculator wraps."""
        self.values = values

    def __add__(self, other):
        """Print self + other, elementwise."""
        print([x + other for x in self.values])

    def __mul__(self, other):
        """Print self * other, elementwise."""
        print([x * other for x in self.values])

    def __sub__(self, other):
        """Print self - other, elementwise."""
        print([x - other for x in self.values])

    def __truediv__(self, other):
        """Print self / other, elementwise (guards against 0)."""
        if other == 0:
            print("Error: division by zero")
            return
        print([x / other for x in self.values])
